class Solution {
public:
    int minimumScore(std::vector<int>& nums, std::vector<std::vector<int>>& edges) {
        int n = nums.size();
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        std::vector<int> sub_xor(n, 0), tin(n, 0), tout(n, 0);
        int timer = 0;
        auto dfs = [&](auto& self, int u, int p) -> void {
            tin[u] = timer++;
            sub_xor[u] = nums[u];
            for (int v : adj[u]) {
                if (v != p) {
                    self(self, v, u);
                    sub_xor[u] ^= sub_xor[v];
                }
            }
            tout[u] = timer;
        };
        dfs(dfs, 0, -1);
        auto is_ancestor = [&](int u, int v) {
            return tin[u] <= tin[v] && tout[v] <= tout[u];
        };
        int total = sub_xor[0];
        int ans = 1e9;
        int m = edges.size();
        std::vector<int> directed_edges(m);
        for (int i = 0; i < m; ++i) {
            directed_edges[i] = is_ancestor(edges[i][0], edges[i][1]) ? edges[i][1] : edges[i][0];
        }
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                int u = directed_edges[i], v = directed_edges[j];
                int c1, c2, c3;
                if (is_ancestor(u, v)) {
                    c1 = sub_xor[v];
                    c2 = sub_xor[u] ^ sub_xor[v];
                    c3 = total ^ sub_xor[u];
                } else if (is_ancestor(v, u)) {
                    c1 = sub_xor[u];
                    c2 = sub_xor[v] ^ sub_xor[u];
                    c3 = total ^ sub_xor[v];
                } else {
                    c1 = sub_xor[u];
                    c2 = sub_xor[v];
                    c3 = total ^ sub_xor[u] ^ sub_xor[v];
                }
                int hi = std::max({c1, c2, c3}), lo = std::min({c1, c2, c3});
                ans = std::min(ans, hi - lo);
            }
        }
        return ans;
    }
};

class Solution {
    private int timer = 0;
    public int minimumScore(int[] nums, int[][] edges) {
        int n = nums.length;
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; ++i) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int[] subXor = new int[n], tin = new int[n], tout = new int[n];
        timer = 0;
        dfs(0, -1, nums, adj, subXor, tin, tout);
        int total = subXor[0], ans = Integer.MAX_VALUE, m = edges.length;
        int[] childNode = new int[m];
        for (int i = 0; i < m; ++i) {
            childNode[i] = isAncestor(edges[i][0], edges[i][1], tin, tout) ? edges[i][1] : edges[i][0];
        }
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                int u = childNode[i], v = childNode[j];
                int c1, c2, c3;
                if (isAncestor(u, v, tin, tout)) {
                    c1 = subXor[v];
                    c2 = subXor[u] ^ subXor[v];
                    c3 = total ^ subXor[u];
                } else if (isAncestor(v, u, tin, tout)) {
                    c1 = subXor[u];
                    c2 = subXor[v] ^ subXor[u];
                    c3 = total ^ subXor[v];
                } else {
                    c1 = subXor[u];
                    c2 = subXor[v];
                    c3 = total ^ subXor[u] ^ subXor[v];
                }
                int hi = Math.max(c1, Math.max(c2, c3)), lo = Math.min(c1, Math.min(c2, c3));
                ans = Math.min(ans, hi - lo);
            }
        }
        return ans;
    }
    private void dfs(int u, int p, int[] nums, java.util.List<Integer>[] adj, int[] subXor, int[] tin, int[] tout) {
        tin[u] = timer++;
        subXor[u] = nums[u];
        for (int v : adj[u]) {
            if (v != p) {
                dfs(v, u, nums, adj, subXor, tin, tout);
                subXor[u] ^= subXor[v];
            }
        }
        tout[u] = timer;
    }
    private boolean isAncestor(int u, int v, int[] tin, int[] tout) {
        return tin[u] <= tin[v] && tout[v] <= tout[u];
    }
}

